#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    constexpr int MAX_LEN = 19;
    vector<int> count(1 << (MAX_LEN + 1), 0);

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        int node = 1;
        for (int j = i; j < static_cast<int>(s.size()) && j < i + MAX_LEN; ++j) {
            if (s[j] == '4') {
                node *= 2;
            } else if (s[j] == '7') {
                node = node * 2 + 1;
            } else {
                break;
            }
            ++count[node];
        }
    }

    int bestNode = -1;
    int bestLength = 0;
    int maximum = 0;

    for (int length = 1; length <= MAX_LEN; ++length) {
        for (int node = 1 << length; node < (1 << (length + 1)); ++node) {
            if (count[node] > maximum) {
                maximum = count[node];
                bestNode = node;
                bestLength = length;
            }
        }
    }

    if (bestNode == -1) {
        cout << -1;
        return 0;
    }

    string answer;
    for (int bit = bestLength - 1; bit >= 0; --bit) {
        answer += ((bestNode >> bit) & 1) ? '7' : '4';
    }

    cout << answer;
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int count4 = count(s.begin(), s.end(), '4');
    int count7 = count(s.begin(), s.end(), '7');

    if (count4 == 0 && count7 == 0)
        cout << -1;
    else if (count4 >= count7)
        cout << 4;
    else
        cout << 7;

    return 0;
}

